import{_ as e,o as a,c as i,an as l}from"./chunks/framework.CZSJrt3Z.js";const o="/EegFun.jl/v0.8/assets/plot_gui.SEfOtPdU.png",u=JSON.parse('{"title":"Plot GUI","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/plot-gui.md","filePath":"tutorials/plot-gui.md","lastUpdated":null}'),n={name:"tutorials/plot-gui.md"};function r(s,t,d,h,p,c){return a(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="Plot-GUI" tabindex="-1">Plot GUI <a class="header-anchor" href="#Plot-GUI" aria-label="Permalink to &quot;Plot GUI {#Plot-GUI}&quot;">​</a></h1><p>The Plot GUI is a quick-access point for interactively exploring your EEG data. Launch it with a single command and use it to inspect any raw EEG file or saved JLD2 data file — or an entire batch of files at once using filename patterns.</p><h2 id="Launching-the-GUI" tabindex="-1">Launching the GUI <a class="header-anchor" href="#Launching-the-GUI" aria-label="Permalink to &quot;Launching the GUI {#Launching-the-GUI}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">plot_gui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>A window opens with three columns allowing file selection, plot selection, and plot setting type controls.</p><p><img src="`+o+`" alt=""></p><h2 id="GUI-Layout" tabindex="-1">GUI Layout <a class="header-anchor" href="#GUI-Layout" aria-label="Permalink to &quot;GUI Layout {#GUI-Layout}&quot;">​</a></h2><p>The window is divided into three columns.</p><h3 id="Column-1-—-File-and-Plot-Selection" tabindex="-1">Column 1 — File &amp; Plot Selection <a class="header-anchor" href="#Column-1-—-File-and-Plot-Selection" aria-label="Permalink to &quot;Column 1 — File &amp; Plot Selection {#Column-1-—-File-and-Plot-Selection}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Control</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Select Directory</td><td style="text-align:right;">Sets the working directory used for batch file discovery</td></tr><tr><td style="text-align:right;"><em>(directory label)</em></td><td style="text-align:right;">Shows the currently selected directory path</td></tr><tr><td style="text-align:right;">Select File</td><td style="text-align:right;">Opens a file picker to choose a <code>.jld2</code> or raw EEG file</td></tr><tr><td style="text-align:right;"><em>(file / pattern box)</em></td><td style="text-align:right;">Type a filename, full path, or batch pattern directly</td></tr><tr><td style="text-align:right;">Select Layout</td><td style="text-align:right;">Opens a file picker to load an electrode layout (<code>.csv</code>)</td></tr><tr><td style="text-align:right;"><em>(layout label)</em></td><td style="text-align:right;">Shows the currently loaded layout filename</td></tr><tr><td style="text-align:right;">Plot Type</td><td style="text-align:right;">Dropdown — direct plots or category submenus (<em>ICA &gt;</em>, <em>ERP Analysis &gt;</em>, <em>Diagnostic Plots &gt;</em>)</td></tr><tr><td style="text-align:right;"><em>(submenu)</em></td><td style="text-align:right;">Appears when a category is selected; choose the specific plot type</td></tr><tr><td style="text-align:right;"><em>(components box)</em></td><td style="text-align:right;">Active only for ICA plots — enter component numbers to plot</td></tr></tbody></table><h3 id="Column-2-—-Data-Filters" tabindex="-1">Column 2 — Data Filters <a class="header-anchor" href="#Column-2-—-Data-Filters" aria-label="Permalink to &quot;Column 2 — Data Filters {#Column-2-—-Data-Filters}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Control</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Participant</td><td style="text-align:right;">Space/comma-separated integers or ranges (e.g. <code>1 2 3</code> or <code>1:10</code>)</td></tr><tr><td style="text-align:right;">Condition</td><td style="text-align:right;">Condition numbers to include; blank = all</td></tr><tr><td style="text-align:right;">Epoch</td><td style="text-align:right;">Epoch numbers to include; blank = all</td></tr><tr><td style="text-align:right;">Layout</td><td style="text-align:right;">Plot layout: <em>Single</em>, <em>Single Avg</em>, <em>Grid</em>, <em>Topo</em></td></tr><tr><td style="text-align:right;">Channel(s)</td><td style="text-align:right;">Multi-select menu (populated when a layout is loaded)</td></tr><tr><td style="text-align:right;"><em>(selected label)</em></td><td style="text-align:right;">Shows the currently selected channels</td></tr></tbody></table><h3 id="Column-3-—-Axis-Settings" tabindex="-1">Column 3 — Axis Settings <a class="header-anchor" href="#Column-3-—-Axis-Settings" aria-label="Permalink to &quot;Column 3 — Axis Settings {#Column-3-—-Axis-Settings}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Control</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">X Limits</td><td style="text-align:right;">Min / max for the time axis</td></tr><tr><td style="text-align:right;">Y Limits</td><td style="text-align:right;">Min / max for the amplitude axis</td></tr><tr><td style="text-align:right;">Z Limits</td><td style="text-align:right;">Min / max for the colour axis (TF and ERP Image)</td></tr><tr><td style="text-align:right;">Baseline</td><td style="text-align:right;">Start / end times in seconds for baseline correction</td></tr><tr><td style="text-align:right;">Baseline Type TF</td><td style="text-align:right;">Baseline normalisation method for Time-Frequency plots</td></tr><tr><td style="text-align:right;">Invert Y axis</td><td style="text-align:right;">Checkbox — flips the Y axis (ERP, Epochs, ERP Image)</td></tr><tr><td style="text-align:right;">PLOT</td><td style="text-align:right;">Triggers the selected plot</td></tr></tbody></table><h2 id="Step-by-Step:-Plotting-a-Single-File" tabindex="-1">Step-by-Step: Plotting a Single File <a class="header-anchor" href="#Step-by-Step:-Plotting-a-Single-File" aria-label="Permalink to &quot;Step-by-Step: Plotting a Single File {#Step-by-Step:-Plotting-a-Single-File}&quot;">​</a></h2><h3 id="1.-Pick-a-directory" tabindex="-1">1. Pick a directory <a class="header-anchor" href="#1.-Pick-a-directory" aria-label="Permalink to &quot;1. Pick a directory {#1.-Pick-a-directory}&quot;">​</a></h3><p>Click <strong>Select Directory</strong> to set the working directory.</p><p>For <strong>batch mode</strong> (pattern input) this is essential — it tells the GUI where to search for matching files. If left unset, the GUI falls back to <code>pwd()</code>, which is the directory Julia was launched from and is rarely where your data lives.</p><p>For <strong>single-file mode</strong> (Select File picks a full path) the directory is not required.</p><h3 id="2.-Select-a-file" tabindex="-1">2. Select a file <a class="header-anchor" href="#2.-Select-a-file" aria-label="Permalink to &quot;2. Select a file {#2.-Select-a-file}&quot;">​</a></h3><p>Either:</p><ul><li><p>Click <strong>Select File</strong> and navigate to a <code>.jld2</code> or raw EEG file, or</p></li><li><p>Type the filename directly into the text box.</p></li></ul><p>The text box accepts full paths, relative paths, or just a filename if the directory is already set.</p><h3 id="3.-Choose-a-plot-type" tabindex="-1">3. Choose a plot type <a class="header-anchor" href="#3.-Choose-a-plot-type" aria-label="Permalink to &quot;3. Choose a plot type {#3.-Choose-a-plot-type}&quot;">​</a></h3><p>Click the <strong>Plot Type</strong> dropdown and select one of the direct plot types:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Selection</th><th style="text-align:right;">Produces</th></tr></thead><tbody><tr><td style="text-align:right;">Data Browser</td><td style="text-align:right;">Interactive scrollable signal browser</td></tr><tr><td style="text-align:right;">Epochs</td><td style="text-align:right;">Epoch-level waveform viewer</td></tr><tr><td style="text-align:right;">ERP</td><td style="text-align:right;">ERP waveforms</td></tr><tr><td style="text-align:right;">ERP Image</td><td style="text-align:right;">Heatmap of individual epochs</td></tr><tr><td style="text-align:right;">Topography</td><td style="text-align:right;">Scalp topographic map</td></tr><tr><td style="text-align:right;">Time-Frequency</td><td style="text-align:right;">Time-frequency power plot</td></tr></tbody></table><p>For more specialised plots, select a <strong>category</strong> to reveal a submenu:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Category</th><th style="text-align:right;">Submenu options</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>ICA &gt;</strong></td><td style="text-align:right;">Components (topographies), Activation (time-course)</td></tr><tr><td style="text-align:right;"><strong>ERP Analysis &gt;</strong></td><td style="text-align:right;">ERP GUI</td></tr><tr><td style="text-align:right;"><strong>Diagnostic Plots &gt;</strong></td><td style="text-align:right;">Channel Summary, Layout View</td></tr></tbody></table><h3 id="4.-Configure-controls-optional" tabindex="-1">4. Configure controls (optional) <a class="header-anchor" href="#4.-Configure-controls-optional" aria-label="Permalink to &quot;4. Configure controls (optional) {#4.-Configure-controls-optional}&quot;">​</a></h3><p>All controls are optional — leave them blank to use sensible defaults.</p><p><strong>X / Y / Z limits</strong> — Enter a min and max value in the paired text boxes to constrain the plotted time range (X), amplitude scale (Y), or colour scale (Z). Both boxes must be filled for the limit to apply.</p><p><strong>Baseline</strong> — Enter start and end times in seconds (e.g. <code>-0.2</code> and <code>0.0</code>) and choose a correction method from the dropdown.</p><p><strong>Channels</strong> — If a layout file is loaded, pick one or more channels from the Channels menu. Click <strong>Select</strong> to clear the selection.</p><p><strong>Layout</strong> — Choose how channels are arranged:</p><ul><li><p><em>Single</em> — all selected channels overlaid on one axis</p></li><li><p><em>Grid</em> — one axis per channel in a grid</p></li><li><p><em>Topo</em> — channels positioned according to their electrode locations</p></li><li><p><em>Single Avg</em> — channels averaged together before plotting</p></li></ul><p><strong>Invert Y axis</strong> — Tick this checkbox to plot positive deflections downward, matching the neurophysiology convention used in some ERP labs. Applies to ERP, Epochs, and ERP Image plots.</p><h3 id="5.-Click-Plot" tabindex="-1">5. Click Plot <a class="header-anchor" href="#5.-Click-Plot" aria-label="Permalink to &quot;5. Click Plot {#5.-Click-Plot}&quot;">​</a></h3><p>Click the <strong>Plot</strong> button. The plot opens in a new window.</p><hr><h2 id="Batch-Mode-Pattern-Input" tabindex="-1">Batch Mode (Pattern Input) <a class="header-anchor" href="#Batch-Mode-Pattern-Input" aria-label="Permalink to &quot;Batch Mode (Pattern Input) {#Batch-Mode-Pattern-Input}&quot;">​</a></h2><p>Instead of a single filename, type a <strong>filename pattern</strong> into the file box. EegFun will discover all matching <code>.jld2</code> files in the selected directory and plot them one after another.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Example: type this into the file box</span></span>
<span class="line"><span>erps_final</span></span></code></pre></div><p>This matches any file containing <code>erps_final</code> in the directory (e.g. <code>01_erps_final.jld2</code>, <code>02_erps_final.jld2</code>, …).</p><h3 id="Filtering-by-participant" tabindex="-1">Filtering by participant <a class="header-anchor" href="#Filtering-by-participant" aria-label="Permalink to &quot;Filtering by participant {#Filtering-by-participant}&quot;">​</a></h3><p>Enter participant numbers in the <strong>Participant</strong> box (space- or comma-separated integers, or ranges):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 2 3         # participants 1, 2, and 3</span></span>
<span class="line"><span>1:10          # participants 1 through 10</span></span>
<span class="line"><span>1 3 5:8       # mixed</span></span></code></pre></div><p>If the box is empty, all matching participants are plotted.</p><h3 id="Filtering-by-condition" tabindex="-1">Filtering by condition <a class="header-anchor" href="#Filtering-by-condition" aria-label="Permalink to &quot;Filtering by condition {#Filtering-by-condition}&quot;">​</a></h3><p>Enter condition numbers in the <strong>Condition</strong> box using the same syntax. Leave blank to plot all conditions.</p><div class="tip custom-block github-alert"><p class="custom-block-title">If you enter a participant ID that does not exist in the discovered files, the GUI will warn you and list the available IDs before plotting.</p><p></p></div><hr><h2 id="ICA-Plots" tabindex="-1">ICA Plots <a class="header-anchor" href="#ICA-Plots" aria-label="Permalink to &quot;ICA Plots {#ICA-Plots}&quot;">​</a></h2><p>Select <strong>ICA &gt;</strong> from the Plot Type dropdown to see two options.</p><p><strong>Components</strong> — Plots the ICA component topographies. The file must be an <code>InfoIca</code> <code>.jld2</code> produced by <code>run_ica()</code>.</p><p><strong>Activation</strong> — Plots the ICA component activation time-courses. The GUI automatically locates the original EEG source file from the path stored inside the <code>InfoIca</code> object. If the source file is a raw format (<code>.bdf</code>, <code>.set</code>, <code>.vhdr</code>), a 0.1 Hz high-pass filter and average rereference are applied automatically before plotting.</p><p>Use the <strong>Components</strong> text box to restrict which components are shown:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1:10          # first ten components</span></span>
<span class="line"><span>1 3 5         # specific components</span></span>
<span class="line"><span>              # (blank = all components)</span></span></code></pre></div><hr><h2 id="Layout-File" tabindex="-1">Layout File <a class="header-anchor" href="#Layout-File" aria-label="Permalink to &quot;Layout File {#Layout-File}&quot;">​</a></h2><p>Some plot types (Data Browser with a raw <code>.bdf</code> file, Layout View) require an electrode layout. Click <strong>Select Layout</strong> to load a <code>.csv</code> layout file. The channel list in the Channels menu is then populated from the layout.</p><hr><h2 id="Tips" tabindex="-1">Tips <a class="header-anchor" href="#Tips" aria-label="Permalink to &quot;Tips {#Tips}&quot;">​</a></h2><ul><li><p><strong>Data Browser</strong> with a <code>.bdf</code> file requires a layout to be loaded.</p></li><li><p><strong>Z limits</strong> apply only to Time-Frequency and ERP Image plots (colour axis).</p></li><li><p><strong>Baseline</strong> fields apply to ERP and Time-Frequency plots.</p></li><li><p>The GUI state is preserved between plots — change one setting at a time to compare results.</p></li><li><p>If a plot fails, a brief warning appears in the Julia REPL. The GUI remains open and usable.</p></li></ul><h2 id="Next-Steps" tabindex="-1">Next Steps <a class="header-anchor" href="#Next-Steps" aria-label="Permalink to &quot;Next Steps {#Next-Steps}&quot;">​</a></h2><ul><li><p><strong>Preprocessing your data</strong> — <a href="./manual-preprocessing">Manual Preprocessing</a> or <a href="./batch-processing">Batch Processing</a> to produce clean epochs and ERPs to explore in the GUI</p></li><li><p><strong>Layouts</strong> — <a href="./layouts-neighbors">Layouts and Neighbours</a> for loading the layout file required by topographic and data browser plots</p></li><li><p><strong>Artifact review</strong> — <a href="./artifact-handling">Artifact Handling</a> for the <code>detect_bad_epochs_interactive</code> GUI workflow</p></li></ul>`,65)])])}const y=e(n,[["render",r]]);export{u as __pageData,y as default};
